// ——— 15 · Rencontres, combat, impression, repos ———
function encountersPage(){
 const lib=state.gmLibrary||{templates:[],encounters:[]};const templates=lib.templates||[],encounters=lib.encounters||[];
 const values=(t)=>({name:t.name||'',kind:t.kind||'monstre',hpMax:t.hpMax??20,ac:t.ac??12,initiative:t.initiative??0,speed:t.speed??9,visibility:t.visibility||'hidden',showHp:!!t.showHp,actions:t.actions||'',notes:t.notes||'',icon:t.icon||'',cr:t.cr||''});
 const fields=(v)=>`<div class="two-fields"><label>Nom du modèle<input required name="name" maxlength="70" value="${attr(v.name)}" placeholder="Ex. Gardien de la crypte"></label><label>Type<select name="kind">${option('monstre','Monstre',v.kind)}${option('pnj','PNJ',v.kind)}</select></label></div>
 <div class="three-fields"><label>PV max<input required type="number" min="1" max="100000" name="hpMax" value="${v.hpMax}"></label><label>CA<input required type="number" min="1" max="40" name="ac" value="${v.ac}"></label><label>Initiative réelle<input required type="number" min="-99" max="99" name="initiative" value="${v.initiative}"></label></div>
 <div class="two-fields"><label>Vitesse (m)<input required name="speed" type="number" min="0" max="200" value="${v.speed}"></label><label>Visibilité initiale<select name="visibility">${option('hidden','Caché aux joueurs',v.visibility)}${option('public','Révélé aux joueurs',v.visibility)}</select></label></div>
 ${crSelect('cr',v.cr)}<label class="inline-check"><input type="checkbox" name="showHp" ${v.showHp?'checked':''}> Autoriser l’affichage des PV si révélé</label>
 <label>Icône fantasy (facultative)<select name="icon"><option value="">Aucune (illustration manuelle possible ensuite)</option>${A.byKind('npc').map(x=>option(x.id,x.name+' · '+x.artist,v.icon)).join('')}</select></label>
 <label>Attaques et dés physiques<textarea name="actions" maxlength="1200" rows="2">${esc(v.actions)}</textarea></label><label>Notes confidentielles<textarea name="notes" maxlength="1500" rows="2">${esc(v.notes)}</textarea></label>`;
 return `<div class="intro-row">${heading('','Bibliothèque MJ')}</div>
 <section class="panel" data-tab="monstres"><div class="panel-top"><h3>Mes monstres et PNJ (bestiaire maison)</h3><span class="mini-pill">${templates.length} / 60</span><button type="button" class="btn btn-primary" data-task="tpl-new">＋ Créer un monstre</button></div>
 <p class="muted small">Créez vos propres créatures avec leur fiche complète (caractéristiques, actions, actions légendaires, défenses) ou partez d’une créature du SRD. Elles servent dans vos rencontres et apparaissent dans la recherche du bestiaire en combat. Jamais envoyées aux joueurs.</p>
 <div class="encounter-list">${templates.map(t=>`<article class="encounter-row"><div class="panel-top"><div class="encounter-heading">${libraryThumb('template',t)}<div><strong>${esc(t.name)}</strong><p class="muted small">${t.kind==='pnj'?'PNJ':'Monstre'}${t.cr?' · FP '+esc(t.cr):''} · ${t.hpMax} PV · CA ${t.ac} · ${t.visibility==='hidden'?'Masqué':'Visible'}</p></div></div><div class="btn-group"><button class="btn btn-secondary" data-template-edit="${attr(t.id)}">Modifier la fiche</button><button class="btn btn-secondary" data-template-delete="${attr(t.id)}">Supprimer</button></div></div>${t.actions?`<p class="muted small"><b>Actions :</b> ${esc(t.actions.slice(0,240))}${t.actions.length>240?'…':''}</p>`:''}</article>`).join('')||'<p class="muted small">Aucune créature maison pour le moment. « Créer un monstre », ou « Ajouter aux modèles » depuis le bestiaire SRD ci-dessous.</p>'}</div>
 ${(state.combat.npcs||[]).length?`<div class="encounter-import"><h4>Importer depuis le combat</h4><div class="encounter-list">${state.combat.npcs.map(n=>`<div class="encounter-import-row"><span>${esc(n.name)} · ${n.hpMax} PV · CA ${n.ac}</span><button class="btn btn-secondary" data-template-from-npc="${attr(n.id)}">Enregistrer comme modèle</button></div>`).join('')}</div></div>`:''}</section>
 ${homebrewItemsSection()}
 ${shopsAdminSection()}
 ${B?(needSrd(),'')+`<section class="panel" data-tab="monstres"><div class="panel-top"><h3>Bestiaire SRD</h3><span class="mini-pill">${B.fullLoaded()?B.list().length+' créatures':'chargement…'} · CC BY 4.0</span></div><p class="muted small">Créatures du SRD prêtes à l’emploi : ajoutez-les à vos modèles en un clic, puis composez vos rencontres. Les dés à lancer sont indiqués, rien n’est tiré par l’application.</p>${liveFilter('.bestiary-row',B.list().length,'Filtrer le bestiaire')}${bestiaryHabitatFilter()}<div class="bestiary-list">${B.list().map(m=>`<div class="bestiary-row ${bestiaryHidden(m)?'hab-hidden':''}"><details class="bestiary-details"><summary><strong>${esc(m.name)}</strong>${altNames(m)?` <small class="muted">(${esc(altNames(m))})</small>`:''} <small class="muted">${esc(m.type)} · FP ${esc(m.cr)} (${m.xp} XP) · ${m.hp} PV · CA ${m.ac}${Object.keys(m.defenses).length?' · '+Object.entries(m.defenses).map(([t,v])=>({resist:'rés.',vuln:'vuln.',immune:'imm.'}[v])+' '+t.toLowerCase()).join(', '):''}</small></summary><div class="bestiary-text">${m.srd&&R?`<button type="button" class="btn btn-secondary" data-monster-sheet="${attr(m.srd)}">Fiche officielle en français</button>`:''}<p><b>Caractéristiques :</b> FOR ${m.abilities.str} · DEX ${m.abilities.dex} · CON ${m.abilities.con} · INT ${m.abilities.int} · SAG ${m.abilities.wis} · CHA ${m.abilities.cha} · vitesse ${m.speed} m</p>${m.actions?`<p><b>Actions :</b> ${esc(m.actions)}</p>`:''}${m.traits?`<p><b>Traits :</b> ${esc(m.traits)}</p>`:''}${m.legendary?`<p><b>Légendaire :</b> ${esc(m.legendary)}</p>`:''}</div></details><button type="button" class="btn btn-secondary" data-bestiary-template="${attr(m.id)}" ${templates.some(t=>t.name===m.name)?'disabled':''}>${templates.some(t=>t.name===m.name)?'Déjà dans vos modèles':'Ajouter aux modèles'}</button></div>`).join('')}</div></section>`:''}
 <section class="panel" data-tab="rencontres"><div class="panel-top"><h3>Rencontres préparées</h3><span class="mini-pill">${encounters.length} / 40</span></div><p class="muted small">Créez une rencontre, ajoutez un ou plusieurs groupes de modèles, puis placez tous leurs exemplaires dans l’initiative. Vous pourrez encore ajuster les valeurs avec les dés physiques. Les créatures déjà présentes ne sont pas effacées.</p>
 <form id="encounter-new-form" class="encounter-compact"><label>Nom de la rencontre<input name="name" maxlength="90" required placeholder="Ex. Embuscade sur la route"></label><label>Notes secrètes du MJ<textarea name="notes" maxlength="1000" rows="2" placeholder="Scène, déclencheurs, renforts..."></textarea></label><button class="btn btn-primary" type="submit">＋ Préparer une rencontre</button></form>
 <div class="encounter-list">${encounters.map(e=>{const total=e.groups.reduce((n,g)=>n+g.quantity,0);return `<article class="encounter-card"><div class="panel-top"><div><h3>${esc(e.name)}</h3><span class="mini-pill">${e.groups.length} groupes · ${total} créatures</span>${difficultyLine(e.groups.flatMap(g=>{const t=templates.find(x=>x.id===g.templateId);return Array(g.quantity).fill(t?.cr||null);}))}</div><div class="btn-group"><button type="button" class="btn btn-primary" data-encounter-deploy="${attr(e.id)}" ${total===0||state.combat.started?'disabled':''}>Ajouter à la table</button><button type="button" class="btn btn-secondary" data-encounter-delete="${attr(e.id)}">Supprimer</button></div></div>${e.notes?`<p class="muted small">Notes MJ : ${esc(e.notes)}</p>`:''}
 <div class="encounter-list">${e.groups.map(g=>{const t=templates.find(x=>x.id===g.templateId);return `<div class="encounter-group"><span><strong>${g.quantity} × ${esc(t?.name||'Modèle absent')}</strong> ${t?`<small>· ${t.hpMax} PV · CA ${t.ac}</small>`:''}</span><button class="text-button" data-group-remove="${attr(g.id)}" data-for="${attr(e.id)}">Retirer</button></div>`;}).join('')||'<p class="muted small">Ajoutez le premier groupe ci-dessous.</p>'}</div>
 <form class="encounter-group-form" data-encounter-id="${attr(e.id)}"><label>Modèle<select name="templateId" required>${templates.map(t=>option(t.id,t.name,'')).join('')}</select></label><label>Nombre<input name="quantity" type="number" value="1" min="1" max="12" required></label><button class="btn btn-secondary" type="submit" ${!templates.length?'disabled':''}>＋ Ajouter ce groupe</button></form>
 <details class="encounter-editor"><summary>Renommer ou modifier les notes</summary><form class="encounter-update-form" data-encounter-id="${attr(e.id)}"><label>Nom<input name="name" required maxlength="90" value="${attr(e.name)}"></label><label>Notes secrètes<textarea name="notes" rows="2" maxlength="1000">${esc(e.notes||'')}</textarea></label><button class="btn btn-secondary" type="submit">Enregistrer</button></form></details>
 </article>`;}).join('')||'<p class="muted small">Aucune rencontre préparée.</p>'}</div></section>
 <section class="panel" data-tab="rencontres"><h3>Fonctionnement pendant la partie</h3><p class="muted small">Le MJ sélectionne une rencontre hors combat, clique sur « Ajouter à la table », puis saisit les initiatives obtenues avec les vrais dés dans « Combat & initiative ». Les nouvelles créatures sont des copies indépendantes : leurs PV et conditions évoluent sans modifier le modèle.</p></section>`;
}
function timerPanel(){const all=[...state.characters,...(state.combat.npcs||[])];
 const pairs=all.flatMap(p=>(p.conditions||[]).map(c=>({id:p.id,name:p.name,c})));
 const nameOf=id=>(all.find(x=>x.id===id)||{}).name||'?';
 const timers=(state.combat.timers||[]).map(t=>{const p=all.find(x=>x.id===t.id);return p?{...t,name:p.name}:null;}).filter(Boolean);
 const label=t=>(t.rounds?(t.when==='start'?'début':'fin')+' du '+(t.rounds>1?t.rounds+'e ':'prochain ')+'tour de '+((t.anchor||t.id)===t.id?'la cible':nameOf(t.anchor)):'')+(t.save?(t.rounds?' · ':'')+'JS '+t.save+' à chaque fin de tour':'');
 const list=timers.length?`<ul class="timer-list">${timers.map(t=>`<li><span><strong>${esc(t.name)}</strong> · ${esc(t.condition)}</span><span class="mini-pill">${esc(label(t))}</span><button type="button" class="text-button" data-task="timer-clear:${attr(t.id)}|${attr(t.condition)}" aria-label="Retirer la durée de ${attr(t.condition)} pour ${attr(t.name)}">Retirer</button></li>`).join('')}</ul>`:'<div class="empty">Aucune durée en cours.</div>';
 const order=(state.combat.order||[]).map(id=>all.find(x=>x.id===id)).filter(Boolean);
 const form=pairs.length?`<div class="timer-form"><label>État<select id="timer-target">${pairs.map(x=>`<option value="${attr(x.id)}|${attr(x.c)}">${esc(x.name)} · ${esc(x.c)}</option>`).join('')}</select></label>
  <label>Jusqu’<select id="timer-when"><option value="end">à la fin</option><option value="start">au début</option></select></label>
  <label>du tour n°<input id="timer-rounds" type="number" min="0" max="99" value="1" aria-describedby="timer-help"></label>
  <label>de<select id="timer-anchor"><option value="">la cible elle-même</option>${order.map(p=>`<option value="${attr(p.id)}">${esc(p.name)}</option>`).join('')}</select></label>
  <label>Sauvegarde à refaire (facultatif)<input id="timer-save" maxlength="50" placeholder="Ex. Sagesse DD 13"></label>
  <button type="button" class="btn btn-secondary" data-task="timer-set">Minuter</button></div>
  <p id="timer-help" class="muted small">« 1 » = jusqu’à la fin de son prochain tour. 1 minute = 10 rounds. « de » : la créature dont le tour compte (souvent le lanceur du sort). La sauvegarde est rappelée au MJ à chaque fin de tour de la cible ; 0 tour = rappel seul, sans fin automatique.</p>`:'<p class="muted small">Appliquez d’abord un état à une créature ou à un personnage.</p>';
 return `<section class="panel timer-panel"><div class="panel-top"><h3>Durées d’états</h3><span class="mini-pill">${timers.length} en cours</span></div><p class="muted small">L’état se retire tout seul au moment choisi.</p>${list}${form}</section>`;}
// Minuteur de tour (facultatif) : affichage seulement, le MJ garde la main sur « Tour suivant ».
function turnTimerControl(){const t=state.combat.turnTimer||0;return `<label class="turn-timer-ctl small">⏱<select data-turn-timer-set aria-label="Minuteur de tour">${[[0,'sans minuteur'],[30,'30 s'],[45,'45 s'],[60,'1 min'],[90,'1 min 30'],[120,'2 min'],[180,'3 min']].map(([v,l])=>`<option value="${v}" ${t===v?'selected':''}>${l}</option>`).join('')}</select></label>${t?'<button type="button" class="text-button" data-task="turn-timer-restart">Relancer</button>':''}`;}
function turnTimerBadge(big){const c=state.combat;if(!c?.started||!c.turnTimer||!c.turnStartedAt)return '';return `<span class="turn-timer${big?' big':''}" data-turn-timer data-start="${attr(c.turnStartedAt)}" data-total="${c.turnTimer}" role="timer" aria-live="off">${fmtSec(timerLeft(c.turnStartedAt,c.turnTimer))}</span>`;}
function timerLeft(start,total){return Math.max(0,Math.round(total-(Date.now()-Date.parse(start))/1000));}
function fmtSec(n){return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
let turnTimerBuzzed='';
if(typeof setInterval==='function'&&typeof document!=='undefined'&&typeof document.querySelectorAll==='function')setInterval(()=>{for(const el of document.querySelectorAll('[data-turn-timer]')){const left=timerLeft(el.dataset.start,Number(el.dataset.total));el.textContent=left>0?'⏱ '+fmtSec(left):'Temps écoulé';el.classList.toggle('low',left>0&&left<=10);el.classList.toggle('over',left===0);
 if(left===0&&actor!=='mj'&&L.activeId(state)===actor&&turnTimerBuzzed!==el.dataset.start){turnTimerBuzzed=el.dataset.start;try{navigator.vibrate?.([200,100,200]);}catch{}}}},1000);
function combatDetails(){if(actor!=='mj'&&state.combat?.started)return playerTurnPanel()+myCompanionsStrip()+combatDetailsInner();return myCompanionsStrip()+combatDetailsInner();}
function combatDetailsInner(){const isGM=actor==='mj';const npcs=state.combat.npcs||[];const all=[...state.characters,...npcs];const ordered=state.combat.order.map(id=>all.find(p=>p.id===id)).filter(Boolean);const current=ordered.find(p=>p.id===L.activeId(state));const turn=state.combat.privateTurn?'Tour privé du MJ':current?'Tour de '+current.name:'Tour non défini';return `
 <div class="intro-row">${isGM&&MD?'<div></div>':heading('','Combat')}
 ${isGM?`<div class="btn-group"><button type="button" class="btn btn-secondary" data-task="party-view" title="Sauvegardes, scores passifs et DD de tout le groupe">Vue du groupe</button><button type="button" class="btn btn-secondary" data-task="table-screen" title="Carte et initiative pour une TV, sans aucun secret">Écran de table</button><button type="button" class="btn btn-secondary" data-task="rest-short-all" ${state.combat.started?'disabled':''} title="Ressources de repos court pour tout le groupe ; chacun dépense ses dés de vie depuis sa fiche">Repos court (groupe)</button><button type="button" class="btn btn-secondary" data-task="rest-all" ${state.combat.started?'disabled':''}>Repos long (groupe)</button><button type="button" class="btn btn-secondary" data-task="gm-screen" title="Aide-mémoire des règles">Écran du MJ</button><button type="button" class="btn btn-secondary" data-task="party-view" title="Sauvegardes et scores passifs du groupe">Vue du groupe</button>${!state.combat.started?`<button class="btn btn-primary" data-task="start" ${!isGM?'disabled':''}>▶ Commencer le combat</button>`:`${undoBtn()}<button class="btn btn-primary" data-task="next" ${!isGM?'disabled':''}>Tour suivant</button>${turnTimerBadge()}${isGM?turnTimerControl():''}<button class="btn btn-secondary" data-task="end" ${!isGM?'disabled':''}>Terminer</button>`}</div>`:''}</div>
 <section class="combat-band"><div><h2>${state.combat.started?'Round '+state.combat.round:'Prêt pour le combat'}</h2><p>${state.combat.started?esc(turn):'Réglez les initiatives lancées avec les vrais dés.'}</p></div><div class="round-badge">${state.combat.started?'R'+state.combat.round:'⚔'}</div></section>
 <div class="combat-grid"><section class="panel initiative-panel"><div class="panel-top"><h3>Ordre d’initiative</h3><span class="mini-pill">${ordered.length} participants visibles</span></div><p class="muted small">Déclarez les initiatives obtenues avec de vrais dés. Le MJ départage les égalités avec ↑ et ↓. Aucun dé n'est lancé par Chroniques.</p>
 ${isGM?`<div class="init-tools"><button class="btn btn-secondary" data-task="sort-initiative" ${state.combat.started?'disabled':''}>Trier par initiatives</button><span class="muted small">${state.combat.manualOrder?'Ordre ajusté manuellement':'Tri automatique avant combat'}</span><label class="inline-check small" title="Indemne, blessé, en sang, au bord de la mort"><input type="checkbox" data-health-words ${state.healthWords!==false?'checked':''}> États de santé visibles des joueurs</label></div>`:''}<div class="initiative-list">${initRows(ordered).map(({p,i,members})=>{const npc=p.id.startsWith('npc-');const hpText=members.length>1?(members.every(m=>isGM||m.showHp)?members.map(m=>m.hp+'/'+m.hpMax).join(' · ')+' PV':members.map(m=>isGM||m.showHp?m.hp+'/'+m.hpMax+' PV':healthName(m.health)||'?').join(' · ')):npc?((isGM||p.showHp)?(p.hp+' / '+(p.hpMax)+' PV'):(p.health?healthName(p.health):'PV réservés au MJ')):(p.form?.hpMax?((p.form.srd&&B&&B.get(p.form.srd)?.name)||p.form.name)+' '+p.form.hp+'/'+p.form.hpMax+' PV · ':'')+(p.hp+'/'+p.stats.hp+' PV');return `<div class="init-item ${members.some(at)?'playing':''} ${members.length>1?'init-group':''}"><div class="init-rank">${i+1}</div><div class="init-details"><strong>${members.length>1?esc(groupName(members))+' <span class="mini-pill">×'+members.length+'</span>':esc(p.name)}</strong><small>${npc?(p.kind==='pnj'?'PNJ':'Monstre'):(esc(p.job))} · ${esc(hpText)}${members.length>1?' · un seul tour pour le groupe':''}</small>${members.length===1?surpriseCtl(p,isGM):''}</div>${isGM&&members.length>1?'<div class="init-reorder" aria-hidden="true"></div>':''}${isGM&&members.length===1?`<div class="init-reorder"><button type="button" data-initiative-move="-1" data-for="${attr(p.id)}" ${i===0||(state.combat.started&&i-1<=state.combat.index)?'disabled':''} aria-label="Monter ${attr(p.name)}">↑</button><button type="button" data-initiative-move="1" data-for="${attr(p.id)}" ${i===ordered.length-1||(state.combat.started&&i<=state.combat.index)?'disabled':''} aria-label="Descendre ${attr(p.name)}">↓</button></div>`:''}<label class="init-value"><span class="visually-hidden">Initiative ${esc(p.name)}</span><input type="number" value="${p.initiative}" min="-99" max="99" data-init="${attr(p.id)}" ${!isGM?'disabled':''}></label>${isGM&&members.length===1?turnOptions(p):''}</div>`;}).join('')}</div></section>
 <section class="panel"><div class="panel-top"><h3>Actions du tour</h3><span class="mini-pill">Suivi manuel</span></div>${isGM?`<p class="muted small">Choisissez un PJ pour ses actions, états et ressources. Pour les monstres, utilisez le panneau MJ ci-dessous.</p><div class="combat-char-pick"><label for="combat-character">Personnage suivi</label><select id="combat-character">${state.characters.map(p=>option(p.id,p.name,selected)).join('')}</select></div>`:''}${quickEconomy(L.findPc(state,selected))}${isGM?combatConcentration(L.findPc(state,selected))+combatConditions(L.findPc(state,selected)):(()=>{const q=L.findPc(state,selected),lab='États et concentration';return `<details class="ux-fold" data-fold="${lab}" ${openFolds.has(lab)?'open':''}><summary>${lab}${q&&q.conditions.length?` (${q.conditions.length>1?`${q.conditions.length} actifs`:`${q.conditions.length} actif`})`:''} <span aria-hidden="true">⌄</span></summary><div class="ux-fold-content">${combatConcentration(q)}${combatConditions(q)}</div></details>`;})()}<button class="btn btn-secondary full" data-char="${attr(selected)}">Fiche et capacités détaillées</button></section></div>
 ${isGM?uxFold('Monstres et PNJ · suivi avancé',creaturePanel()):''}
 ${isGM?uxFold('Durées d’états',timerPanel()):''}
 ${uxFold('Journal du combat',`<section class="panel journal"><div class="panel-top"><h3>Journal du combat</h3><span class="mini-pill">${state.combat.log.length} événements</span></div>${state.combat.log.length?state.combat.log.slice(0,18).map(x=>`<div class="log-row"><time>${esc(x.when)}</time><span>${esc(x.msg)}</span></div>`).join(''):'<div class="empty">Les événements apparaîtront ici pendant la partie.</div>'}</section>`)}`;}
// --- V4.3 : vue du groupe pour le MJ, alertes à 0 PV, actions de repaire ---
const lastHp={};let downAlerts=[];
function trackDowned(){if(actor!=='mj'||!state?.characters)return;for(const p of state.characters){const prev=lastHp[p.id];if(prev!==undefined&&prev>0&&p.hp<=0&&!downAlerts.includes(p.id)){downAlerts.push(p.id);setTimeout(()=>toast(p.name+' tombe à 0 PV : jets contre la mort à son tour.',true),0);}if(p.hp>0)downAlerts=downAlerts.filter(x=>x!==p.id);lastHp[p.id]=p.hp;}}
function downBanner(){const pcs=downAlerts.map(id=>L.findPc(state,id)).filter(p=>p&&p.hp<=0);if(!pcs.length)return '';return `<div class="alert-banner danger" role="alert"><p><strong>À terre :</strong> ${pcs.map(p=>esc(p.name)+' ('+(p.deathSaves?.success||0)+' succès · '+(p.deathSaves?.failure||0)+' échec'+((p.deathSaves?.failure||0)>1?'s':'')+')').join(', ')}. Jets contre la mort au début de leur tour ; tout soin les relève.</p><button type="button" class="text-button" data-task="down-dismiss">Masquer</button></div>`;}
function lairBanner(){const ids=state.combat?.lairPending||[];if(!ids.length)return '';const ns=ids.map(id=>(state.combat.npcs||[]).find(n=>n.id===id)).filter(Boolean);if(!ns.length)return '';
 return `<div class="alert-banner lair" role="status"><div><strong>Initiative 20 — actions de repaire</strong>${ns.map(n=>`<details><summary>${esc(n.name)}</summary><p class="small">${esc(n.lair)}</p></details>`).join('')}</div><button type="button" class="btn btn-secondary" data-task="lair-done">Fait</button></div>`;}
function partyOverview(){if(actor!=='mj')return '';const pcs=(state.characters||[]).filter(p=>!p.fallen);if(!pcs.length)return '';
 return `<section class="party-overview" aria-label="Le groupe en un coup d’œil">${pcs.map(p=>{const max=p.stats?.hp||1,pct=Math.max(0,Math.min(100,Math.round(p.hp/max*100))),state_=p.hp<=0?'down':pct<=33?'low':pct<=66?'mid':'ok';const conds=(p.conditions||[]).map(c=>typeof c==='string'?c:c.name).filter(Boolean);
  return `<article class="po-card po-${state_}"><div class="po-top"><strong>${esc(p.name)}</strong><span class="po-hp">${p.hp}${p.tempHp?'+'+p.tempHp:''} / ${max} PV</span></div><div class="po-bar" aria-hidden="true"><i style="width:${pct}%"></i></div><div class="po-stats"><span title="Classe d’armure">CA ${p.stats?.ac??'—'}</span><span title="Perception passive">Perc. ${p.stats?.passive??'—'}</span>${p.concentration?`<span title="Concentration">${esc(p.concentration)}</span>`:''}${p.exhaustion?`<span>Épuis. ${p.exhaustion}</span>`:''}${p.inspiration?'<span title="Inspiration héroïque">Inspiration</span>':''}${p.hp<=0?`<span class="po-death">${p.deathSaves?.success||0}/3 · ${p.deathSaves?.failure||0}/3</span>`:''}</div><button type="button" class="text-button po-insp" data-inspiration="${p.inspiration?'remove':'give'}" data-for="${attr(p.id)}" aria-pressed="${!!p.inspiration}" aria-label="${p.inspiration?'Retirer l’inspiration héroïque à ':'Accorder l’inspiration héroïque à '}${attr(p.name)}">${p.inspiration?'Inspiré':'Inspirer'}</button>${conds.length?`<div class="po-conds">${conds.map(c=>`<span class="mini-pill">${esc(c)}</span>`).join('')}</div>`:''}</article>`;}).join('')}</section>`;}
// --- V4.4 : fiche imprimable (Imprimer → « Enregistrer au format PDF ») ---
function sheetMod(v){if(!Number.isInteger(v))return '—';const m=Math.floor((v-10)/2);return (m>=0?'+':'')+m;}
function printableSheet(p){const ab=p.stats?.abilities||{},cls=p.progression?.classId||P.detectClass(p.job),info=CG?CG.info(cls):null,prog=P.progression(p,state.edition),pb=2+Math.floor((Math.max(1,p.level)-1)/4);
 const saveSet=new Set(info?info.saves:[]);const sign=n=>n==null?'—':(n>=0?'+':'')+n;
 const abilityBox=(k,l)=>{const v=ab[k];const m=Number.isInteger(v)?Math.floor((v-10)/2):null;return `<div class="ps-ab"><small>${l}</small><strong>${v??'—'}</strong><span>${sheetMod(v)}</span><em>Sauv. ${m==null?'—':sign(m+(saveSet.has(k)?pb:0))}${saveSet.has(k)?' ●':''}</em></div>`;};
 const skills=Object.entries(P.SKILLS).map(([id,[name,key]])=>{const v=P.skillValue(p,id),rank=p.progression?.skills?.[id]||(p.origin?.grantedSkills?.includes(id)?'trained':'none');return `<li><span>${rank==='expert'?'◆':rank==='trained'?'●':'○'} ${esc(name)} <small>(${(ABILITY_LABELS.find(([k])=>k===key)||[])[1]})</small></span><b>${sign(v)}</b></li>`;}).join('');
 const spells=(p.grimoire||[]).map(e=>{const sp=e.spellId&&S?S.get(e.spellId):e.custom;return sp?{name:sp.name,level:sp.level,prepared:e.prepared}:null;}).filter(Boolean).sort((a,b)=>a.level-b.level||a.name.localeCompare(b.name,'fr'));
 const items=p.inventoryItems||[],coins=p.coins||{};const eq=GEAR&&cls?GEAR.equipmentAc(p,cls):null;
 const block=(t,body)=>body?`<section class="ps-block"><h3>${t}</h3>${body}</section>`:'';
 return `<article class="print-sheet"><header class="ps-head"><div><h1>${esc(p.name)}</h1><p>${esc(p.role)} · ${esc(p.job)}${p.progression?.subclass?' ('+esc(p.progression.subclass)+')':''}${P.isMulticlass&&P.isMulticlass(p)?' · '+esc(P.classLabel(p)):''} · niveau ${p.level}</p></div><div class="ps-meta">${esc(state.title||'')}<br>Règles ${esc(state.edition||'')} · ${esc(new Date().toLocaleDateString('fr-FR'))}</div></header>
 <div class="ps-core"><div><small>CA</small><strong>${p.stats.ac}</strong></div><div><small>PV max</small><strong>${p.stats.hp}</strong><span>actuels : ____</span></div><div><small>Initiative</small><strong>${sign(p.initiative)}</strong></div><div><small>Vitesse</small><strong>${p.speed} m</strong></div><div><small>Maîtrise</small><strong>+${pb}</strong></div><div><small>Perception passive</small><strong>${p.stats.passive??'—'}</strong></div>${info?`<div><small>Dé de vie</small><strong>${p.level}d${info.die}</strong></div>`:''}</div>
 <div class="ps-cols"><div class="ps-col"><div class="ps-abilities">${ABILITY_LABELS.map(([k,l])=>abilityBox(k,l)).join('')}</div>${block('Compétences',`<ul class="ps-skills">${skills}</ul><p class="ps-legend">non maîtrisée · ● maîtrise · ◆ expertise · ● après « Sauv. » : sauvegarde maîtrisée</p>`)}</div>
 <div class="ps-col">${block('Actions et capacités',(p.abilities||[]).length?`<ul class="ps-list">${p.abilities.map(x=>`<li><b>${esc(x.name)}</b> <small>${esc({action:'action',bonus:'action bonus',reaction:'réaction',free:'libre',passive:'passive'}[x.type]||x.type||'')}</small>${x.description?' — '+esc(x.description):''}</li>`).join('')}</ul>`:'')}
 ${block('Ressources',(p.resources||[]).length?`<ul class="ps-list">${p.resources.map(r=>`<li><b>${esc(r.name)}</b> : ${'☐'.repeat(Math.min(20,r.max||0))} <small>(${r.max}, repos ${r.rest==='short'?'court':'long'})</small></li>`).join('')}</ul>`:'')}
 ${block('Dons',(p.feats||[]).length?`<ul class="ps-list">${p.feats.map(f=>`<li><b>${esc(f.name)}</b>${f.description?' — '+esc(f.description):''}</li>`).join('')}</ul>`:'')}
 ${block('Sorts',spells.length||prog.spells?.slots?.length?`${prog.spells?.slots?.length?`<p>Emplacements : ${prog.spells.slots.map((n,i)=>n?'niv. '+(i+1)+' '+'☐'.repeat(n):'').filter(Boolean).join(' · ')}</p>`:''}${spells.length?`<ul class="ps-list ps-spells">${spells.map(s=>`<li>${s.level===0?'Tour':'Niv. '+s.level} — ${esc(s.name)}${s.prepared&&s.level>0?' ✓':''}</li>`).join('')}</ul>`:''}`:'')}
 ${block('Équipement',`${eq&&eq.reliable?`<p>CA d’équipement : ${eq.ac} (${esc(eq.parts.join(' · '))})</p>`:''}${items.length?`<ul class="ps-list ps-items">${items.map(it=>`<li>${it.equipped?'⚔ ':''}${esc(it.name)}${(it.quantity??1)>1?' ×'+it.quantity:''}${it.chargesMax?' · charges '+it.charges+'/'+it.chargesMax:''}${it.attuned?' · harmonisé':''}</li>`).join('')}</ul>`:'<p>—</p>'}<p>Bourse : ${I.MONEY.map(k=>(coins[k]||0)+' '+(GEAR?GEAR.COIN_FR[k]:k)).join(' · ')}</p>`)}
 ${block('Notes',p.notes?`<p class="ps-notes">${esc(p.notes)}</p>`:'')}</div></div>
 <footer class="ps-foot">Chroniques · fiche générée le ${esc(new Date().toLocaleString('fr-FR'))}. Les dés restent physiques.</footer></article>`;}
function printSheetModal(id){const p=L.findPc(state,id);if(!p)return '';return `<div class="modal-backdrop"><div class="modal modal-wide" role="dialog" aria-modal="true" aria-labelledby="print-title"><div class="panel-top"><h2 id="print-title">Fiche imprimable</h2><button class="icon-close" data-task="close-modal" aria-label="Fermer">✕</button></div><p class="muted small">« Imprimer » ouvre la fenêtre d’impression du navigateur : choisissez votre imprimante, ou « Enregistrer au format PDF ». Sur téléphone : Partager → Imprimer, puis enregistrer en PDF.</p><div class="btn-group"><button type="button" class="btn btn-primary" data-print-now="${attr(p.id)}">Imprimer / PDF</button></div><div class="print-preview">${printableSheet(p)}</div></div></div>`;}
function printNow(id){const p=L.findPc(state,id);if(p)printHtml(printableSheet(p));}
function printHtml(html){let root=document.getElementById('print-root');if(!root){root=document.createElement('div');root.id='print-root';document.body.appendChild(root);}root.innerHTML=html;document.documentElement.classList.add('print-mode');
 const done=()=>{document.documentElement.classList.remove('print-mode');window.removeEventListener('afterprint',done);};window.addEventListener('afterprint',done);window.print();setTimeout(done,60000);}
// --- V4.5 : cartes de sorts imprimables ---
const CAST_FR={action:'1 action',bonus:'1 action bonus',reaction:'1 réaction',minute:'1 minute',ritual:'rituel'};
function spellCardsHtml(p){const list=(p.grimoire||[]).map(e=>({e,s:S.spellFor(e)})).filter(x=>x.s).sort((a,b)=>a.s.level-b.s.level||a.s.name.localeCompare(b.s.name,'fr'));let magic=null;try{magic=G.stats(p,P);}catch{}
 if(!list.length)return '';return `<article class="print-cards"><header class="ps-head"><div><h1>Sorts de ${esc(p.name)}</h1><p>${esc(p.job)} · niveau ${p.level}${magic&&magic.saveDC!=null&&magic.attack!=null?` · DD ${magic.saveDC} · attaque ${magic.attack>=0?'+':''}${magic.attack} (${esc(magic.abilityLabel)})`:''}</p></div></header><div class="spell-cards">${list.map(({e,s})=>`<section class="spell-card"><div class="sc-top"><strong>${esc(s.name)}</strong><span>${s.level===0?'Tour de magie':'Niveau '+s.level}</span></div>
 <dl><div><dt>Incantation</dt><dd>${esc(CAST_FR[s.castTime]||s.castTime||'—')}${s.ritual?' · rituel':''}</dd></div><div><dt>Portée</dt><dd>${esc(s.range||'—')}</dd></div><div><dt>Composantes</dt><dd>${esc(s.components||'—')}</dd></div><div><dt>Durée</dt><dd>${s.concentration?'Concentration, ':''}${esc(s.duration||'—')}</dd></div></dl>
 ${s.diceHint?`<p class="sc-dice">${esc(s.diceHint)}</p>`:''}${(()=>{const t=R&&R.loaded()&&e.spellId?R.spellCardText(e.spellId):null;return t?`<p class="sc-text">${esc(t.text)}</p>${t.cut?'<p class="sc-notes">Suite : voir Règles du jeu dans Chroniques.</p>':''}`:'<p class="sc-notes">Effet (voir le livre ou le SRD) :</p><div class="sc-lines"></div>';})()}${e.prepared&&s.level>0?'<span class="sc-prep">Préparé</span>':''}</section>`).join('')}</div></article>`;}
// --- V4.5 : livre de campagne ---
function bookHtml(gmVersion){const isGM=actor==='mj'&&gmVersion;const planner=state.campaignPlanner||{};const sessions=[state.sessionStats,...(state.sessionHistory||[])].filter(Boolean).filter(x=>isGM||x.published).sort((a,b)=>String(a.startedAt).localeCompare(String(b.startedAt)));
 const docs=(state.handouts||[]).filter(h=>isGM?h.sentAt||actor==='mj':true);const mem=(state.campaignMemory||[]).filter(m=>isGM||m.visibility==='shared').slice().sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));
 const part=(t,b)=>b?`<section class="book-part"><h2>${t}</h2>${b}</section>`:'';
 return `<article class="print-book"><header class="book-cover"><p>Chroniques</p><h1>${esc(state.title||'Campagne')}</h1><p>${esc(state.characters.map(p=>p.name).join(' · '))}</p><p class="ps-meta">${isGM?'Édition du MJ (avec les secrets)':'Édition des joueurs'} · ${esc(new Date().toLocaleDateString('fr-FR'))}</p></header>
 ${part('Les aventuriers',`<ul>${state.characters.map(p=>`<li><b>${esc(p.name)}</b> — ${esc(p.role)} ${esc(p.job)}, niveau ${p.level}</li>`).join('')}</ul>`)}
 ${part('Séances',sessions.length&&SS?sessions.map(x=>`<div class="book-entry"><h3>${esc(fmtSession(x.startedAt,{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</h3><ul>${SS.lines(x,{audience:isGM?'gm':'player',party:state.characters.length}).map(l=>`<li>${esc(l)}</li>`).join('')||'<li>Rien de noté.</li>'}</ul></div>`).join(''):'')}
 ${part('Mémoire de campagne',mem.length?mem.map(m=>`<div class="book-entry"><h3>${esc(m.title)}${m.date?' <small>'+esc(m.date)+'</small>':''}</h3>${m.summary?`<p>${esc(m.summary)}</p>`:''}${m.impact?`<p><i>${esc(m.impact)}</i></p>`:''}${isGM&&m.gmNotes?`<p class="book-secret">MJ : ${esc(m.gmNotes)}</p>`:''}</div>`).join(''):'')}
 ${part('Documents',docs.length?docs.map(h=>`<div class="book-entry"><h3>${esc(h.title)}</h3>${h.text?`<p class="ps-notes">${esc(h.text)}</p>`:''}</div>`).join(''):'')}
 ${PLANNER_TYPES.map(([type,label])=>{const list=(planner[type]||[]).filter(e=>isGM||e.visibility==='shared');return part(label,list.length?list.map(e=>`<div class="book-entry"><h3>${esc(e.title)}${e.attitude?' <small>'+esc(ATTITUDE_LABELS[e.attitude]||'')+'</small>':''}</h3>${e.context?`<p><i>${esc(e.context)}</i></p>`:''}${e.summary?`<p>${esc(e.summary)}</p>`:''}${isGM&&e.privateNotes?`<p class="book-secret">MJ : ${esc(e.privateNotes)}</p>`:''}</div>`).join(''):'');}).join('')}
 ${CHR?part('Frise de la campagne',(()=>{const tl=CHR.timeline(state,{isGM});return tl.length?`<ul>${tl.map(x=>`<li><b>${esc(new Date(x.at).toLocaleDateString('fr-FR'))}</b> — ${esc(x.title)}${x.text?' : '+esc(x.text):''}</li>`).join('')}</ul>`:'';})()):''}
 ${CHR?part('Bilan',(()=>{const st=CHR.arcStats(state,{isGM});return st.total.sessions||st.pcs.some(p=>p.xp)?`<p>Séances : ${st.total.sessions}, combats : ${st.total.combats}, adversaires vaincus : ${st.total.defeated}.</p><table class="book-table"><tr><th>Personnage</th><th>XP</th><th>Niveaux</th><th>Dégâts encaissés</th><th>PV soignés</th><th>Chutes</th></tr>${st.pcs.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.xp}</td><td>${p.levels}</td><td>${p.damage}</td><td>${p.healing}</td><td>${p.downs}</td></tr>`).join('')}</table>`:'';})()):''}
 ${part('Histoires des aventuriers',state.characters.filter(p=>(p.history||[]).length).map(p=>`<div class="book-entry"><h3>${esc(p.name)}</h3><ul>${(p.history||[]).filter(e=>isGM||!e.gm).map(e=>`<li><small>${esc(new Date(e.at).toLocaleDateString('fr-FR'))}${e.world?' · '+esc(e.world):''}</small> ${e.gm?'<span class="book-secret">[MJ] </span>':''}${esc(e.text)}</li>`).join('')}</ul></div>`).join(''))}
 ${part('Cartes',(state.maps||[]).filter(m=>(m.hasImage||m.filename)&&(isGM||m.visibility==='shared')).map(m=>`<figure class="book-map"><img src="/api/map-image/${attr(m.id)}" alt="${attr(m.title)}"><figcaption>${esc(m.title)}</figcaption></figure>`).join(''))}
 <footer class="ps-foot">Livre généré par Chroniques le ${esc(new Date().toLocaleString('fr-FR'))}.</footer></article>`;}
function printBook(){if(actor==='mj'){modal='book';render();return;}printHtml(bookHtml(false));}
function bookModal(){return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="book-title"><div class="panel-top"><h2 id="book-title">Livre de campagne</h2><button class="icon-close" data-task="close-modal" aria-label="Fermer">✕</button></div><p class="muted small">Résumés de séance, mémoire, documents et carnet réunis dans un PDF. Choisissez « Enregistrer au format PDF » dans la fenêtre d’impression.</p><div class="btn-group"><button type="button" class="btn btn-primary" data-book="players">Édition des joueurs (sans secrets)</button><button type="button" class="btn btn-secondary" data-book="gm">Édition du MJ (avec notes secrètes)</button></div></div></div>`;}
// --- V4.5 : repos guidé ---
function restShortModal(id){const p=L.findPc(state,id);if(!p)return '';const cls=p.progression?.classId||P.detectClass(p.job),info=CG?CG.info(cls):null,pool=P.isMulticlass&&P.isMulticlass(p)?P.hitDice(p):null,die=pool&&pool.length?pool[0].die:info?info.die:null,avail=Math.max(0,p.level-(p.hitDiceUsed||0)),con=CG?CG.mod(p.stats?.abilities?.con??10):0;
 return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="rest-title"><div class="panel-top"><h2 id="rest-title">Repos court · ${esc(p.name)}</h2><button class="icon-close" data-task="close-modal" aria-label="Fermer">✕</button></div>
 <p>PV : <strong>${p.hp} / ${p.stats.hp}</strong> · Dés de vie disponibles : <strong>${avail} / ${p.level}</strong>${pool&&pool.length>1?` (${pool.map(x=>x.count+'d'+x.die).join(' + ')} au total ; Constitution ${con>=0?'+':''}${con} par dé)`:die?` (d${die}, Constitution ${con>=0?'+':''}${con} par dé)`:''}</p>
 <form id="rest-short-form" data-pc="${attr(p.id)}" data-die="${die||12}" data-con="${con}"><div class="two-fields"><label>Dés de vie dépensés<input name="dice" type="number" min="0" max="${avail}" value="${avail&&p.hp<p.stats.hp?1:0}"></label><label>Total obtenu aux dés<input name="total" type="number" min="0" max="${avail*(die||12)}" placeholder="Lancez vos d${die||'?'}"></label></div>
 <p class="muted small" id="rest-preview">Lancez les dés de vie choisis, saisissez leur total : la Constitution est ajoutée pour chaque dé. Les capacités « repos court » sont restaurées.</p><button class="btn btn-primary" type="submit">Prendre le repos court</button></form>
 <p class="muted small">Au repos long, tous les PV reviennent ; les dés de vie reviennent ${state.edition==='2024'?'tous (règles 2024)':'à moitié (règles 2014)'}.</p></div></div>`;}
// 5.14 : surprise (avant le combat ou au premier round).
function surpriseCtl(p,isGM){const on=(state.combat.surprised||[]).includes(p.id);const open=!state.combat.started||state.combat.round===1;
 const hint=state.edition==='2024'?'désavantage à l’initiative':'ni déplacement ni action au premier tour';
 if(isGM&&open)return `<button type="button" class="chip surprise-chip" data-surprise="${attr(p.id)}" aria-pressed="${on}" title="${attr('Surpris : '+hint)}">${on?'Surpris':'Surprise ?'}</button>${on&&!state.combat.started?`<span class="muted small surprise-hint">${esc(hint)}</span>`:''}`;
 return on?`<span class="mini-pill surprise-pill" title="${attr(hint)}">Surpris</span>`:'';}
function restShortAllPrompt(){if(actor!=='mj')return;actUndoable('restShortAll',{},'Repos court appliqué à tout le groupe.');}
function restAllPrompt(){if(actor!=='mj')return;actUndoable('restLongAll',{},'Repos long appliqué à tout le groupe.');}
// --- V4.5 : XP et jalons ---
function sessionXp(){const ss=state.sessionStats;return ss?(ss.defeated||[]).reduce((t,d)=>t+(d.xp||0),0):0;}
function xpLine(p){if(!CG)return '';const next=CG.XP_LEVELS[p.level];return `XP : ${(Number(p.xp)||0).toLocaleString('fr-FR')}${next!=null&&p.level<20?' / '+next.toLocaleString('fr-FR')+' pour le niveau '+(p.level+1):''}`;}
function rewardsPanel(){if(actor!=='mj')return '';const xp=sessionXp(),pcs=state.characters||[];return `<section class="panel" id="xp-award" data-tab="resumes"><div class="panel-top"><h3>Récompenses : XP et jalons</h3>${xp?`<span class="mini-pill">${xp.toLocaleString('fr-FR')} XP vaincus cette séance</span>`:''}</div>
 <p class="muted small">Distribuez l’expérience (le niveau disponible est signalé sur la fiche), ou utilisez les jalons : un clic et les personnages choisis peuvent passer au niveau suivant.</p>
 <form id="xp-form"><div class="three-fields"><label>XP<input name="amount" type="number" min="1" max="1000000" value="${xp||''}" placeholder="Ex. 450"></label><label>Répartition<select name="mode"><option value="split">À partager entre eux</option><option value="each">Pour chacun</option></select></label><label>Raison (facultatif)<input name="reason" maxlength="80" placeholder="Ex. Embuscade des gobelins"></label></div>
 <fieldset class="split-who"><legend>Personnages</legend>${pcs.map(p=>`<label class="inline-check"><input type="checkbox" name="ids" value="${attr(p.id)}" checked> ${esc(p.name)} <small class="muted">${esc(xpLine(p))}</small></label>`).join('')}</fieldset>
 <div class="btn-group"><button class="btn btn-primary" type="submit" name="act" value="xp">Distribuer l’XP</button><button class="btn btn-secondary" type="submit" name="act" value="milestone">Jalon : niveau suivant</button></div></form></section>`;}
// --- V4.5 : écran de table (TV, vidéoprojecteur) ---
// 5.5 : spectateur (lien « /#spectateur=… ») : même écran que la TV, sans compte, actualisé toutes les 4 secondes.
const spectatorToken=typeof location!=='undefined'&&/^#spectateur=([A-Za-z0-9_-]{20,80})$/.exec(location.hash||'')?.[1]||'';
const tableMode=typeof location!=='undefined'&&(location.hash==='#ecran-table'||!!spectatorToken);
function openTableScreen(){try{window.open('/#ecran-table','chroniques-ecran-table');}catch{}toast('Écran de table ouvert dans une nouvelle fenêtre : placez-la sur la TV et passez en plein écran.');}
async function refreshTable(){try{const r=await api(spectatorToken?'spectate-state?t='+encodeURIComponent(spectatorToken):'table-state');viewer=r.viewer;version=r.version;state=r.state;actor='__table__';renderTable();}catch(e){$('#app').innerHTML=`<div class="auth-page"><div class="auth-card"><h1>Écran de table</h1><p>${esc(e.message)}</p><p>${spectatorToken?'Demandez un nouveau lien spectateur au MJ.':'Ouvrez cette page depuis le compte du MJ.'}</p></div></div>`;}}
function renderTable(){const app=$('#app');if(!app||!state)return;const maps=state.maps||[];const map=maps.find(m=>m.id===state.tableMapId&&m.hasImage)||maps.find(m=>m.hasImage);const ratio=map?(mapAspect[map.id]||1):1;
 const all=[...(state.characters||[]),...(state.combat?.npcs||[])];const order=(state.combat?.order||[]).map(id=>all.find(p=>p.id===id)).filter(Boolean);const active=state.combat?.started?state.combat.order[state.combat.index]:null;
 const stage=map?`<div class="campaign-map-stage table-stage ${map.grid?.cells&&map.grid?.shape!=='hex'?'with-grid':''}" style="--grid:${Number(map.grid?.cells)||1};width:min(100%,calc(96vh * ${ratio}))"><img class="campaign-map-image" src="/api/map-image/${encodeURIComponent(map.id)}" alt="" draggable="false" data-map-image="${attr(map.id)}">${map.grid?.cells&&map.grid?.shape!=='hex'?'<div class="map-grid" aria-hidden="true"></div>':''}${hexSvg(map,ratio,false)}${areasSvg(map,ratio)}${drawingsSvg(map)}${pingsHtml(map.id)}${(map.tokens||[]).filter(t=>t.kind!=='pc'&&(!map.fog?.enabled||fogVisible(map,t.x,t.y))).map(t=>mapTokenHtml(map,t)).join('')}${map.fog?.enabled?fogSvg(map,ratio,false):''}${(map.tokens||[]).filter(t=>t.kind==='pc').map(t=>mapTokenHtml(map,t)).join('')}</div>`:`<div class="ts-empty"><h1>${esc(state.title||'Chroniques')}</h1>${nextSessionCard()}</div>`;
 const sp=state.spotlight;const spot=sp?`<div class="ts-spotlight"><img src="${attr(sp.builtinId?A.src(sp.builtinId):'/api/media/'+encodeURIComponent(sp.mediaId))}" alt=""><p>${esc(sp.title||'')}</p></div>`:'';
 const activeName=active?(all.find(p=>p.id===active)?.name||''):'';const recapShow=state.recapTable&&!state.combat?.started;
 patchApp(`<div class="table-screen"><main class="ts-main">${activeName?`<div class="ts-turn" role="status">Au tour de <strong>${esc(activeName)}</strong> · round ${state.combat.round}</div>`:''}${recapShow?`<div class="ts-recap table-recap">${CHR?CHR.paragraphs(state.recapTable,esc):esc(state.recapTable)}</div>`:stagedScene()?stageView('stage-view stage-table'):stage}</main><aside class="ts-side"><h2>${esc(state.title||'')}</h2>${state.worldTime?.enabled&&WTC?`<p class="ts-date">${esc(WTC.season(state.worldTime,state.worldTime.minutes).icon)} ${esc(WTC.format(state.worldTime,state.worldTime.minutes))}</p>`:''}${state.weather?weatherLine(state.weather,'ts-weather'):''}${CLKM&&(state.clocks||[]).some(c=>c.visible)?`<div class="ts-clocks">${state.clocks.filter(c=>c.visible).map(c=>`<div class="ts-clock">${CLKM.svg(c,44)}<span>${esc(c.label)}</span></div>`).join('')}</div>`:''}${turnTimerBadge(true)}${state.combat?.started?`<p class="ts-round">Round ${state.combat.round}</p><ol class="ts-init">${order.map(p=>{const pc=(state.characters||[]).some(c=>c.id===p.id);const hp=pc?p.hp+' / '+p.stats.hp:(p.showHp?p.hp+' / '+p.hpMax:'');const hw=!pc&&!p.showHp&&state.healthWords!==false?(p.health||(N&&N.health?N.health(p.hp,p.hpMax):'')):'';return `<li class="${p.id===active?'active':''} ${pc?'pc':'npc'} ${(pc?p.hp:p.hp)<=0&&(hp||hw)?'down':''}"><span>${esc(p.name)}</span>${hp?`<small>${hp} PV</small>`:hw?`<small class="health-word health-${hw}">${esc(healthName(hw))}</small>`:''}</li>`;}).join('')}</ol>`:`<p class="ts-round">Hors combat</p>`}<button type="button" class="ts-full" data-ts-full>Plein écran</button></aside>${spot}</div>`);syncAudio();if(audioBlocked)showSoundUnlock();}
function combat(){
 if(actor!=='mj'||!MD)return combatDetails();
 return `<div class="intro-row combat-title">${heading('','Combat')}</div><div class="mj-view-tabs" role="group" aria-label="Affichage de combat du Maître du Jeu">
 <button type="button" class="mj-view-tab ${gmCombatView==='desk'?'active':''}" data-mj-view="desk" aria-pressed="${gmCombatView==='desk'}">Bureau de combat</button>
 <button type="button" class="mj-view-tab ${gmCombatView==='board'?'active':''}" data-mj-view="board" aria-pressed="${gmCombatView==='board'}">Tableau MJ</button>
 <button type="button" class="mj-view-tab ${gmCombatView==='detail'?'active':''}" data-mj-view="detail" aria-pressed="${gmCombatView==='detail'}">Initiative et détails</button></div>
 ${downBanner()}${lairBanner()}${partyOverview()}${state.groupChecks?.active?groupCheckPanel():''}${state.votes?.active?votePanel():''}
 ${gmCombatView==='desk'?combatDesk():gmCombatView==='board'?mjDashboardHtml():combatDetails()}`;
}
// Le bureau n'existe que dans la projection privée MJ ; aucun nouvel endpoint ni dé virtuel.
function fightPanel(id,body,index){const p=fightLayout.panels[id];if(!p?.visible)return '';
 return `<article class="workspace-panel fight-panel ${p.wide?'workspace-wide':''}" data-fight-panel="${id}" aria-label="${esc(CW.LABELS[id])}">
 <header class="workspace-panel-header"><span draggable="true" class="workspace-grip" data-fight-drag="${id}" title="Déplacer sur ordinateur">⠿</span><h3>${esc(CW.LABELS[id])}</h3>
 <div class="workspace-panel-actions"><button type="button" data-fight-step="up" data-fight-id="${id}" aria-label="Monter ${esc(CW.LABELS[id])}" ${index===0?'disabled':''}>↑</button>
 <button type="button" data-fight-step="down" data-fight-id="${id}" aria-label="Descendre ${esc(CW.LABELS[id])}" ${index===fightLayout.order.length-1?'disabled':''}>↓</button>
 <button type="button" data-fight-size="${id}" aria-label="${p.wide?'Réduire':'Agrandir'} ${esc(CW.LABELS[id])}">${p.wide?'▣':'▢'}</button>
 <button type="button" data-fight-hide="${id}" aria-label="Masquer ${esc(CW.LABELS[id])}">×</button></div></header><div class="workspace-panel-body">${body}</div></article>`;
}
function combatDesk(){if(actor!=='mj'||!CW)return '';
 const data=MD.build(state,actor,L,P);
 const all=[...state.characters,...(state.combat.npcs||[])];
 const ordered=(state.combat.order||[]).map(id=>all.find(p=>p.id===id)).filter(Boolean);
 const activeId=L.activeId(state);
 const current=data.privateTurn?'Tour privé du MJ':all.find(p=>p.id===activeId)?.name||'Non défini';
 const npc=state.combat.npcs||[];
 const selectedPc=L.findPc(state,selected)||state.characters[0];
 const status=`<div class="fight-status"><span class="mini-pill">${state.combat.started?'Round '+esc(state.combat.round):'Combat non démarré'}</span><strong>${esc(state.combat.started?current:'Prêt à commencer')}</strong>
 <p class="muted small">${data.alerts||data.pendingChecks?[data.alerts?`${data.alerts>1?`${data.alerts} personnages à surveiller.`:`${data.alerts} personnage à surveiller.`}`:'',data.pendingChecks?`${data.pendingChecks>1?`${data.pendingChecks} sauvegardes de concentration en attente.`:`${data.pendingChecks} sauvegarde de concentration en attente.`}`:''].filter(Boolean).join(' '):'Rien à signaler.'}</p>
 <div class="fight-buttons">${state.combat.started?undoBtn()+'<button type="button" class="btn btn-primary" data-task="next">Tour suivant</button><button type="button" class="btn btn-secondary" data-task="end">Terminer le combat</button>':'<button type="button" class="btn btn-primary" data-task="start">▶ Démarrer le combat</button>'}</div>
 ${state.combat.started?all.filter(p=>p.id===activeId||(state.combat.delayed||[]).some(d=>d.id===p.id)||(state.combat.readied||[]).some(r=>r.id===p.id)).map(p=>{const o=turnOptions(p);return o?`<div class="fight-turnopt"><strong>${esc(p.name)}</strong>${o}</div>`:'';}).join(''):''}</div>
 <p class="muted small">Les initiatives et résultats viennent de vos dés physiques.</p>`;
 const party=`<div class="fight-party-grid">${data.members.map(p=>`<article class="fight-person"><div class="fight-person-name"><span class="fight-initial" aria-hidden="true">${esc(p.name.charAt(0))}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.job)} · niv. ${p.level}</small></div>${p.turn?'<span class="mini-pill">En jeu</span>':''}</div>
 <div class="fight-person-numbers"><b class="${p.hp*2<=p.hpMax?'mj-low':''}">${p.hp}/${p.hpMax} PV</b><span>CA ${p.ac}</span><span>Init. ${p.initiative}</span></div><div class="mj-meter" role="img" aria-label="PV ${p.hp} sur ${p.hpMax}"><span class="${p.hp*2<=p.hpMax?'mj-meter-low':''}" style="width:${pct(p.hp,p.hpMax)}%"></span></div>
 <p class="muted small">${p.conditions.length?esc(p.conditions.join(', ')):'Aucun état'}${p.concentration?' · Concentration : '+esc(p.concentration):''}</p><button type="button" class="btn btn-secondary" data-mj-follow="${attr(p.id)}">Suivre les actions</button></article>`).join('')||'<p class="muted">Aucun personnage.</p>'}</div>`;
 const initiative=`<div class="fight-order">${ordered.map((p,i)=>`<div class="fight-order-item ${p.id===activeId&&state.combat.started?'fight-current':''}"><b>${i+1}</b><span>${esc(p.name)}${(state.combat.surprised||[]).includes(p.id)?' <span class="mini-pill surprise-pill">Surpris</span>':''}</span><strong>${esc(p.initiative)}</strong></div>`).join('')||'<p class="muted">Aucun participant.</p>'}</div><button type="button" class="btn btn-secondary full" data-mj-view="detail">Modifier les initiatives et la surprise</button>`;
 const actions=`${selectedPc?`<label class="fight-select">Personnage suivi<select id="combat-character">${state.characters.map(p=>option(p.id,p.name,selectedPc.id)).join('')}</select></label>${quickEconomy(selectedPc)}${combatConcentration(selectedPc)}<button type="button" class="btn btn-secondary full" data-char="${attr(selectedPc.id)}">Fiche détaillée</button>`:'<p class="muted">Aucun personnage associé.</p>'}`;
 const creatures=`<div class="fight-creatures">${npc.map(n=>`<div class="fight-creature"><div><strong>${esc(n.name)}</strong><small>${n.kind==='pnj'?'PNJ':'Monstre'} · ${esc(n.visibility==='public'?'Révélé':'Masqué')}</small></div><span>${n.hp}/${n.hpMax} PV · CA ${n.ac}</span></div>`).join('')||'<p class="muted">Aucune créature. Préparez une rencontre ou ajoutez un PNJ.</p>'}</div>${ADM?'<button type="button" class="btn btn-secondary full" data-task="area-damage">Dégâts de zone</button>':''}<button type="button" class="btn btn-secondary full" data-mj-view="detail">Gérer les créatures</button>`;
 const journal=`${(state.combat.log||[]).slice(0,10).map(x=>`<div class="fight-log-line"><time>${esc(x.when)}</time><span>${esc(x.msg)}</span></div>`).join('')||'<p class="muted">Le journal sera rempli au fil du combat.</p>'}`;
 const content={turn:status,party,initiative,actions,creatures,journal};
 const visible=CW.IDS.filter(id=>fightLayout.panels[id]?.visible);
 return `<section class="fight-workspace" aria-label="Bureau de combat personnalisable">
 <div class="workspace-heading"><div><p class="muted small">Affichez seulement ce qui vous sert pendant la rencontre. Chaque campagne conserve sa propre disposition sur cet appareil.</p></div>
 <details class="workspace-customize fight-customize" ${fightCustomizeOpen?'open':''}><summary>Personnaliser</summary><div class="workspace-choices"><strong>Afficher les panneaux</strong>${CW.IDS.map(id=>`<label><input type="checkbox" data-fight-show="${id}" ${fightLayout.panels[id].visible?'checked':''}> ${esc(CW.LABELS[id])}</label>`).join('')}<button type="button" class="btn btn-secondary" data-fight-reset>Disposition par défaut</button></div></details></div>
 <div class="workspace-grid fight-grid">${fightLayout.order.map((id,i)=>fightPanel(id,content[id],i)).join('')}</div>${!visible.length?'<p>Réactivez un panneau depuis Personnaliser.</p>':''}</section>`;
}
function mjDashboardHtml(){
 if(actor!=='mj')return '';
 const data=MD.build(state,actor,L,P),list=MD.visibleMembers(data,gmBoardFilter);
 const alerts=data.alerts?`${data.alerts>1?`${data.alerts} personnages à surveiller`:`${data.alerts} personnage à surveiller`}`:'Aucune alerte prioritaire';
 const current=data.privateTurn?'Tour privé du MJ':data.turnId?([ ...data.members,...data.npcs ].find(p=>p.id===data.turnId)?.name||'Tour à identifier'):'—';
 const chip=(s)=>`<span class="mj-board-chip">${esc(s)}</span>`;
 const cards=list.map(p=>`<article class="mj-pc" aria-label="${attr(p.name)}">
 <div class="mj-pc-heading"><div class="mj-portrait" role="img" aria-label="Portrait de ${attr(p.name)}"><span class="avatar-initial" aria-hidden="true">${esc(p.name.charAt(0))}</span>${artwork('character',p.id,'','',p.name)}</div><div class="mj-pc-title"><strong>${esc(p.name)}</strong><small>${esc(p.job)} · niv. ${p.level} · Initiative ${p.initiative}</small></div>${p.turn?'<span class="mj-turn-tag">Tour actuel</span>':''}</div>
 <div class="mj-vitals"><div><small>PV${p.tempHp?' (+ '+p.tempHp+' temp.)':''}</small><b class="${p.hp*2<=p.hpMax?'mj-low':''}">${p.hp}/${p.hpMax}</b></div><div><small>CA</small><b>${p.ac}</b></div><div><small>Déplacement</small><b>${p.movement} m</b></div></div>
 <div class="mj-meter" aria-label="Points de vie ${p.hp} sur ${p.hpMax}"><span style="width:${pct(p.hp,p.hpMax)}%" class="${p.hp*2<=p.hpMax?'mj-meter-low':''}"></span></div>
 <div class="mj-turn-econ" aria-label="Actions restantes"><span class="${p.action?'ready':''}">Action : ${p.action?'prête':'indisponible'}</span><span class="${p.bonus?'ready':''}">Bonus : ${p.bonus?'possible':'non disponible'}</span><span class="${p.reaction?'ready':''}">Réaction : ${p.reaction?'prête':'indisponible'}</span></div>
 <div class="mj-row-tags">${p.conditions.length?p.conditions.map(chip).join(''):chip('Aucune condition')}${p.concentration?chip('Concentration : '+p.concentration):''}</div>
 ${p.checks.length?`<div class="mj-board-warning"><strong>⚠ Sauvegarde de concentration</strong>${p.checks.map(c=>`<div class="mj-save-row"><span>DD ${c.dc} · ${c.damage} dégâts · d20 réel</span><div class="mj-save-buttons"><button class="btn btn-secondary" data-concentration-check="${attr(c.id)}" data-for="${attr(p.id)}" data-result="success">Réussie</button><button class="btn btn-secondary" data-concentration-check="${attr(c.id)}" data-for="${attr(p.id)}" data-result="failure">Ratée</button></div></div>`).join('')}</div>`:''}
 <div class="mj-resource-summary"><small>${p.resources.length?'Capacités : '+p.resources.map(r=>r.name+' '+r.left+'/'+r.max).join(' · '):'Aucune ressource manuelle suivie'}</small><small>${p.spellSlots.tracked?'Emplacements suivis : '+p.spellSlots.left+'/'+p.spellSlots.max:p.spellSlots.hasSlots?'Emplacements non suivis':'Aucun emplacement suivi'}</small></div>
 <div class="mj-card-actions"><button class="btn btn-secondary" type="button" data-char="${attr(p.id)}">Ouvrir la fiche</button><button class="btn btn-secondary" type="button" data-mj-follow="${attr(p.id)}">Suivre les actions</button></div>
 </article>`).join('');
 return `<div class="intro-row"><div></div>
 <div class="btn-group"><button type="button" class="btn btn-secondary" data-task="gm-screen" title="Aide-mémoire des règles">Écran du MJ</button>${ADM?'<button type="button" class="btn btn-secondary" data-task="area-damage" title="Une saisie, plusieurs cibles, sauvegardes et résistances">Dégâts de zone</button>':''}${data.started?`${undoBtn()}<button class="btn btn-primary" data-task="next">Tour suivant</button><button class="btn btn-secondary" data-task="end">Terminer</button>`:`<button class="btn btn-primary" data-task="start">▶ Démarrer le combat</button>`}</div></div>
 <section class="mj-headline"><div><small>${data.started?'Round '+data.round:'Hors combat'}</small><strong>${esc(data.started?current:'Prêt à commencer')}</strong></div><div><small>Alertes</small><strong>${esc(alerts)}</strong></div><div><small>Concentration</small><strong>${data.pendingChecks>1?`${data.pendingChecks} jets en attente`:`${data.pendingChecks} jet en attente`}</strong></div></section>
 <div class="mj-dashboard-toolbar"><div class="mj-filters" role="group" aria-label="Filtrer les personnages">
 ${[['all','Tous ('+data.members.length+')'],['alert','À surveiller ('+data.alerts+')'],['turn','Tour actif']].map(([f,l])=>`<button type="button" data-mj-filter="${f}" aria-pressed="${gmBoardFilter===f}" class="mj-filter ${gmBoardFilter===f?'selected':''}">${esc(l)}</button>`).join('')}
 </div><button type="button" class="btn btn-secondary" data-mj-view="detail">Modifier les initiatives</button></div>
 <div class="mj-pc-grid">${cards||'<div class="panel mj-empty">Aucun aventurier dans ce filtre. Choisissez « Tous » pour revoir le groupe.</div>'}</div>
 ${uxFold('Monstres et PNJ · ' + data.npcs.length,`<section class="panel mj-npc-section"><div class="panel-top"><h3>Monstres et PNJ · ${data.npcs.length}</h3><button class="btn btn-secondary" data-mj-view="detail">Gérer les créatures</button></div>
 ${data.npcs.length?`<div class="mj-npc-grid">${data.npcs.map(n=>`<article class="mj-npc"><div class="mj-npc-head"><strong>${esc(n.name)}</strong>${n.turn?'<span class="mj-turn-tag">Tour actuel</span>':''}</div><div class="mj-row-tags">${chip(n.hidden?'Masqué aux joueurs':'Visible des joueurs')}${chip(n.kind==='pnj'?'PNJ':'Monstre')}</div><p>♥ ${n.hp}/${n.hpMax} PV · CA ${n.ac} · Initiative ${n.initiative}</p>${n.conditions.length?`<div class="mj-row-tags">${n.conditions.map(chip).join('')}</div>`:''}<small>Actions et notes détaillées dans le combat classique.</small></article>`).join('')}</div>`:'<p class="muted">Aucune créature ajoutée. Chargez une rencontre ou créez des monstres depuis la vue détaillée.</p>'}</section>`) }
 <p class="muted small">Les alertes reflètent uniquement les états enregistrés ; elles ne remplacent pas l’arbitrage du MJ. Aucun dé virtuel, aucune conséquence automatique.</p>`;
}
function creaturePanel(){const npcs=state.combat.npcs||[];return `<section class="panel creature-panel"><div class="panel-top"><h3>Bestiaire privé du MJ (${npcs.length>1?`${npcs.length} créatures`:`${npcs.length} créature`})</h3><button type="button" class="btn btn-secondary" data-nav="encounters">Préparer des rencontres</button><button class="btn btn-primary" data-npc-create ${state.combat.started?'disabled':''}>＋ Monstre / PNJ</button></div><p class="muted small">Seul le MJ consulte les PV, CA, actions et notes secrètes. Les créatures masquées n'apparaissent pas chez les joueurs. Terminez le combat pour ajouter/supprimer un participant.</p>
 ${bestiaryPicker()}${liveFilter('.creature-entry',npcs.length,'Filtrer les créatures')}${npcs.length?`<div class="creature-list">${npcs.map(n=>`<article class="creature-entry"><div class="panel-top"><div>${artwork('npc',n.id,'','art-tiny',n.name)}<strong>${esc(n.name)}</strong>${n.cr?` <span class="mini-pill">FP ${esc(n.cr)}</span>`:''} <button type="button" class="text-button" data-pick-image="npc||${attr(n.id)}">Illustration</button> <span class="mini-pill">${n.kind==='pnj'?'PNJ':'Monstre'} · ${n.visibility==='public'?'Visible':'Masqué'}</span><p class="muted small">${n.hp}/${n.hpMax} PV · CA ${n.ac} · ${n.conditions.map(esc).join(', ')||'Aucun état'}</p></div><div class="btn-group"><button type="button" class="btn btn-secondary" data-npc-edit="${attr(n.id)}">Modifier</button><button type="button" class="btn btn-secondary" data-npc-remove="${attr(n.id)}" ${state.combat.started?'disabled':''}>Retirer</button></div></div>
 <p class="muted small"><b>Actions et dés physiques :</b> ${esc(n.actions||'À renseigner par le MJ')} ${n.notes?`<span class="secret-note">· Notes secrètes : ${esc(n.notes)}</span>`:''}</p>
 ${npcConcentrationBlock(n)}${npcActionBar(n)}${npcSpellBlock(n)}${npcStatBlock(n)}
 <div class="npc-controls"><label>Dégâts ou soins (total réel)<input type="number" min="1" max="100000" value="1" data-npc-amount="${attr(n.id)}"></label><button class="btn btn-secondary" data-npc-hp="damage" data-for="${attr(n.id)}">− Dégâts</button><button class="btn btn-secondary" data-npc-hp="heal" data-for="${attr(n.id)}">+ Soins</button><label>Type<select data-npc-type="${attr(n.id)}"><option value="">—</option>${L.DAMAGE_TYPES.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>État<select data-npc-condition="${attr(n.id)}"><option value="">Choisir…</option>${L.STATES.map(x=>option(x,x,'')).join('')}</select></label></div>
 </article>`).join('')}</div>`:'<p class="muted small">Aucune créature enregistrée pour le moment.</p>'}</section>`;}
function combatConcentration(p){if(!p)return '';const own=L.canViewDetail(state,actor,p.id);if(!own)return '';
 const checks=p.concentrationChecks||[],edit=L.canEdit(state,actor,p.id);
 return `<div class="combat-subsection"><h4>Concentration</h4><p class="muted small">${esc(p.concentration||'Aucun sort maintenu')}. En cas de dégâts, lancez physiquement une sauvegarde de Constitution : DD 10 ou moitié des dégâts (arrondie à l’inférieur), le plus élevé. Les autres bonus et exceptions se vérifient à la table.</p>${checks.map(c=>`<div class="concentration-alert"><strong>⚠ Jet physique en attente · DD ${c.dc}</strong><small>${c.damage} dégâts déclarés${c.round?' · round '+c.round:''} · résultat à confirmer</small>${edit?`<div class="init-tools"><button class="btn btn-secondary" data-concentration-check="${attr(c.id)}" data-for="${attr(p.id)}" data-result="success">Réussi</button><button class="btn btn-secondary" data-concentration-check="${attr(c.id)}" data-for="${attr(p.id)}" data-result="failure">Raté</button></div>`:''}</div>`).join('')}</div>`;
}
function combatConditions(p){if(!p||!L.canViewDetail(state,actor,p.id))return '';
 const edit=L.canEdit(state,actor,p.id);return `<div class="combat-subsection"><h4>États du personnage</h4><p class="muted small">Cochez ou retirez les états constatés à la table. Aucun jet automatique et aucune durée expirée sans confirmation.</p><div class="condition-quick-list">${L.STATES.map(c=>`<button class="condition-quick ${p.conditions.includes(c)?'condition-on':''}" title="${attr(conditionHelp(c))}" data-condition="${attr(c)}" ${edit?'':'disabled'} aria-pressed="${p.conditions.includes(c)}">${p.conditions.includes(c)?'✓ ':'＋ '}${esc(c)}</button>`).join('')}</div></div>`;
}
function quickEconomy(p){if(!p)return '<p>Aucun personnage.</p>';const s=L.summary(state,p.id), can=L.canEdit(state,actor,p.id);return `<div class="economy-grid">${econ('Action',s.action,'action','◈',p,can)}${econ('Action bonus',s.bonus,'bonus','✧',p,can)}${econ('Réaction',s.reaction,'reaction','↶',p,can)}<div class="economy-pill"><span>Déplacement</span><strong>${s.movement} m</strong><small>restants sur ${p.speed} m</small></div></div><div class="small muted" style="margin:14px 0">${s.bonus?'Une capacité bonus est actuellement utilisable.':'Action bonus non disponible ou déjà utilisée.'} Les réactions demandent un déclencheur valide.</div>`;}
function econ(name,available,type,icon,p,can){return `<div class="economy-pill ${available?'available':'spent'}"><span>${icon} ${name}</span><strong>${available?'Prête':'Non disponible'}</strong><button type="button" class="tiny-action" data-spend="${type}" data-for="${attr(p.id)}" ${!available||!can?'disabled':''}>Marquer utilisée</button></div>`;}
